def decode(encoded, original, message):
    # Build a mapping from encoded letters to their original letters
    mapping = {}
    for i in range(len(encoded)):
        e = encoded[i]
        o = original[i]
        if e in mapping and mapping[e] != o:
            return "Failed"
        mapping[e] = o
    # Use the mapping to decode the message
    decoded = ""
    for c in message:
        if c in mapping:
            decoded += mapping[c]
        else:
            decoded += c
    return decoded
